\bottomrule
\end{tabular}
\caption{Full grid search results ($\rho{=}0.4$, seed\,42).
$b \in [0.1, 0.5]$ forms a broad plateau (three-seed mean for $b{=}0.1$: $17.655 \pm 0.009$); $b{=}0.3$ is the post-hoc best.}
\label{tab:grid_full}
\end{table}

